package com.aiot.log.controller;
import com.aiot.log.common.ApiResponse; import com.aiot.log.dto.EnvironmentAnnouncementRuleRequest; import com.aiot.log.entity.EnvironmentAnnouncementRule; import com.aiot.log.exception.*; import com.aiot.log.mapper.EnvironmentAnnouncementRuleMapper; import com.aiot.log.mapper.EnvironmentSpaceMapper; import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/environment-announcement-rules") public class EnvironmentAnnouncementRuleController { final EnvironmentAnnouncementRuleMapper rules; final EnvironmentSpaceMapper spaces; public EnvironmentAnnouncementRuleController(EnvironmentAnnouncementRuleMapper r,EnvironmentSpaceMapper s){rules=r;spaces=s;} @GetMapping public ApiResponse<List<EnvironmentAnnouncementRule>> list(@RequestParam(required=false) Long spaceId){LambdaQueryWrapper<EnvironmentAnnouncementRule>w=new LambdaQueryWrapper<>();if(spaceId!=null)w.eq(EnvironmentAnnouncementRule::getSpaceId,spaceId);return ApiResponse.success(rules.selectList(w));} @PostMapping public ApiResponse<EnvironmentAnnouncementRule> create(@Valid @RequestBody EnvironmentAnnouncementRuleRequest q){validate(q); if(spaces.selectById(q.spaceId)==null)throw new BusinessException(ErrorCode.ENVIRONMENT_SPACE_NOT_FOUND);EnvironmentAnnouncementRule r=new EnvironmentAnnouncementRule();fill(r,q);rules.insert(r);return ApiResponse.success(r);} @PutMapping("/{id}") public ApiResponse<EnvironmentAnnouncementRule> update(@PathVariable Long id,@Valid @RequestBody EnvironmentAnnouncementRuleRequest q){validate(q); EnvironmentAnnouncementRule r=rules.selectById(id);if(r==null)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);if(spaces.selectById(q.spaceId)==null)throw new BusinessException(ErrorCode.ENVIRONMENT_SPACE_NOT_FOUND);fill(r,q);rules.updateById(r);return ApiResponse.success(r);} @DeleteMapping("/{id}") public ApiResponse<Void> delete(@PathVariable Long id){rules.deleteById(id);return ApiResponse.success();} void validate(EnvironmentAnnouncementRuleRequest q){if(!"weather_change".equals(q.metric)&&q.thresholdValue==null&&q.changeValue==null)throw new BusinessException(ErrorCode.REQUEST_VALIDATION_FAILED,"请填写绝对阈值或变化幅度");} void fill(EnvironmentAnnouncementRule r,EnvironmentAnnouncementRuleRequest q){r.spaceId=q.spaceId;r.name=q.name.trim();r.metric=q.metric;r.changeValue=q.changeValue;r.thresholdValue=q.thresholdValue;r.consecutiveCount=q.consecutiveCount;r.cooldownMinutes=q.cooldownMinutes;r.quietStart=q.quietStart;r.quietEnd=q.quietEnd;r.enabled=q.enabled;r.bypassQuietForSevere=false;} }
